    let s = v instanceof Date ? v.toISOString().slice(0, 10) : typeof v === "number" ? (Number.isInteger(v) && Math.abs(v) > 20000 && Math.abs(v) < 80000 && window.XLSX ? bankDate(v) || v.toFixed(2) : v.toFixed(2)) : cellText(v);
