  const radio = (name, cur, opts) => '<div class="cp-radios">' + opts.map(([v, l]) => '<label class="cp-item"><input type="radio" name="cp-' + name + '" data-pf="' + name + '" value="' + v + '"' + ((cur || "") === v ? " checked" : "") + "><span>" + l + "</span></label>").join("") + "</div>";
  let body = "", title = "";
