      await saveBooks();
      const rows = TDS.rows(), withPan = rows.filter(r => r.pan).length;
      toast(res.count + " ledgers read. " + Object.keys(res.pans).length + " carry a PAN; " + withPan + " of " + rows.length + " deductions now have one.");
      render();
