// the landing page links here with #register or #signin: show that screen (unless already signed in)
function applyEntryHash(){
  const h = String(location.hash || "").toLowerCase();
  if (h !== "#register" && h !== "#signin") return;
  try { history.replaceState(null, "", location.pathname + location.search); } catch (e){}
  if (Cloud.on() || window.claude) return;
  Cloud.setCfg({gate: true});                  // someone who chose "without an account" earlier still sees the screen asked for
  S.signUpOpen = h === "#register"; Cloud.st.error = "";
}
window.addEventListener("hashchange", () => { applyEntryHash(); render(); });
(async function start(){
  applyEntryHash();
  S.splitPdf = lsGet("tdsdesk-test:splitPdf") === "1";
  S.freeFirst = lsGet("tdsdesk-test:freeFirst") !== "0";
  S.askClaudeNewSupplier = lsGet("tdsdesk-test:askClaudeNew") === "1";
  const samplePromise = (async () => { try { return window.claude && window.claude.use ? await window.claude.use("sample") : null; } catch(e){ return null; } })();
  if (!window.claude) S.sampleReady = false;
  await Store.init();
  try { await Store.loadFirm(); }
  catch (e){ S.firm = S.firm || Object.assign({}, DEFAULT_FIRM); toast("Saved data could not be loaded. Reload the page to try again."); }
  Object.keys(S.data).forEach(refreshStats);
  render();
  const last = lsGet("tdsdesk-test:last") || recentIds()[0];
  if (last && S.companies[last]) openCompany(last);
  S.sample = await samplePromise;
  if (S.sample){
    try { const lim = await S.sample.limits(); S.imgMax = lim && lim.images ? Math.min(6, lim.images.maxCount) : 0; } catch(e){ S.imgMax = 0; }
    try { const perms = await window.claude.use("permissions"); if (perms) S.samplePerm = await perms.state("sample"); } catch(e){}
    document.getElementById("fileIn").accept = "application/pdf,image/*,.jpg,.jpeg,.jfif,.png,.webp,.heic";
  }
  pickEngine();
  S.sampleReady = true;
  probeOcr();
  try { const last = JSON.parse(lsGet("tdsdesk-test:selftest") || "null"); if (last && last.results) S.selfTest = {busy: false, results: last.results, finished: last.finished, remembered: true}; } catch (e){}
  if (wipeStoredKeys()){ pickEngine(); setTimeout(() => toast("For safety, API keys saved in this browser were removed. Sign in to the firm account to use Claude and Google OCR."), 1500); }
  startBridgePolling();
  startCloudSync();
  if (!Cloud.on()) fetch(Cloud.cfg().url.replace(/\/+$/, "") + "/rest/v1/rpc/signup_info", {method: "POST", headers: {apikey: Cloud.cfg().key, "Content-Type": "application/json"}, body: "{}"})
    .then(r => r.json()).then(j => { S.signupInfo = j || {open: false}; render(); }, () => {});
  render();
})();
window.addEventListener("beforeunload", () => { if (S.coId) lsSet("tdsdesk-test:last", S.coId); });


/* ================================================================== */
/* Financial statements: Schedule III (companies) and the ICAI format */
/* for non-corporate entities, from the ledgers in Tally              */
/* ================================================================== */
const FS = {
  // what a group is, from Tally's own flags when the masters are read, else from the reserved names
  nature(l){
    const b = S.books || {}, info = b.groupInfo || {}, path = Books.groupPath(l), top = path[path.length - 1] || "";
    const x = info[top] || info[path[0]];
    if (x) return {rev: x.rev, gp: x.gp, dr: x.dr, path, top};
    const t = top.toLowerCase();
    const R = {"sales accounts": [1, 1, 0], "direct incomes": [1, 1, 0], "indirect incomes": [1, 0, 0], "purchase accounts": [1, 1, 1], "direct expenses": [1, 1, 1], "indirect expenses": [1, 0, 1]};
    if (R[t]) return {rev: !!R[t][0], gp: !!R[t][1], dr: !!R[t][2], path, top};
    return {rev: false, gp: false, dr: /assets|investments|misc\. expenses|suspense|branch/.test(t), path, top};
  },
  // the lines of each format: [id, label, section]
  LINES: {
    co: [["share", "Share capital", "EQ"], ["reserves", "Reserves and surplus", "EQ"], ["ltb", "Long-term borrowings", "NCL"], ["dtl", "Deferred tax liabilities (net)", "NCL"], ["oltl", "Other long-term liabilities", "NCL"], ["ltp", "Long-term provisions", "NCL"],
      ["stb", "Short-term borrowings", "CL"], ["tp", "Trade payables", "CL"], ["ocl", "Other current liabilities", "CL"], ["stp", "Short-term provisions", "CL"],
      ["ppe", "Property, plant and equipment", "NCA"], ["intang", "Intangible assets", "NCA"], ["cwip", "Capital work-in-progress", "NCA"], ["nci", "Non-current investments", "NCA"], ["dta", "Deferred tax assets (net)", "NCA"], ["ltla", "Long-term loans and advances", "NCA"], ["onca", "Other non-current assets", "NCA"],
      ["ci", "Current investments", "CA"], ["inv", "Inventories", "CA"], ["tr", "Trade receivables", "CA"], ["cash", "Cash and cash equivalents", "CA"], ["stla", "Short-term loans and advances", "CA"], ["oca", "Other current assets", "CA"]],
    nc: [["capital", "Owners' capital", "EQ"], ["reserves", "Reserves and surplus", "EQ"], ["ltb", "Long-term borrowings", "NCL"], ["dtl", "Deferred tax liabilities (net)", "NCL"], ["oltl", "Other long-term liabilities", "NCL"], ["ltp", "Long-term provisions", "NCL"],
      ["stb", "Short-term borrowings", "CL"], ["tp", "Trade payables", "CL"], ["ocl", "Other current liabilities", "CL"], ["stp", "Short-term provisions", "CL"],
      ["ppe", "Property, plant and equipment", "NCA"], ["intang", "Intangible assets", "NCA"], ["cwip", "Capital work-in-progress", "NCA"], ["nci", "Non-current investments", "NCA"], ["dta", "Deferred tax assets (net)", "NCA"], ["ltla", "Long-term loans and advances", "NCA"], ["onca", "Other non-current assets", "NCA"],
      ["ci", "Current investments", "CA"], ["inv", "Inventories", "CA"], ["tr", "Trade receivables", "CA"], ["cash", "Cash and bank balances", "CA"], ["stla", "Short-term loans and advances", "CA"], ["oca", "Other current assets", "CA"]]
  },
  PL: [["rev", "Revenue from operations"], ["oth", "Other income"], ["mat", "Cost of materials consumed"], ["pur", "Purchases of stock-in-trade"], ["chg", "Changes in inventories"], ["emp", "Employee benefits expense"],
    ["fin", "Finance costs"], ["dep", "Depreciation and amortisation expense"], ["exp", "Other expenses"], ["exc", "Exceptional items"], ["tax", "Tax expense"]],
  SECTIONS: {EQ: "Shareholders' funds", NCL: "Non-current liabilities", CL: "Current liabilities", NCA: "Non-current assets", CA: "Current assets"},
  cfg(b){ return Object.assign({kind: "co", mfg: false, map: {}, stock: {}, shares: "", face: ""}, (b && b.fs) || {}); },
  // where a ledger goes by rule, before any choice by hand; bal is Tally's sign (a debit is negative)
  place(l, bal, kind){
    const n = this.nature(l), p = n.path.map(g => g.toLowerCase()), has = g => p.includes(g), up = l.toUpperCase();
    if (n.rev){
      if (!n.dr) return n.gp ? "rev" : "oth";
      if (n.gp) return has("purchase accounts") ? "pur" : "exp";
      const txt = up + " " + n.path.join(" ").toUpperCase();
      if (/DEPRECIATION|AMORTI/.test(txt)) return "dep";
      if (/INCOME TAX|PROVISION FOR TAX|DEFERRED TAX/.test(txt)) return "tax";
      if (/EMPLOYEE|SALAR|WAGES|BONUS|STAFF|GRATUITY|\bPF\b|\bESI|PROVIDENT|LEAVE ENCASH|INCENTIVE/.test(txt)) return "emp";
      if (/FINANCE|INTEREST|PROCESSING FEE|LOAN CHARGE|BANK CHARGE/.test(txt) && !/INTEREST ON (TDS|GST|INCOME TAX)/.test(up)) return "fin";
      return "exp";
    }
    if (/PROFIT\s*&\s*LOSS/i.test(l)) return "reserves";
    const dr = bal < 0;
    if (has("capital account")) return has("reserves & surplus") ? "reserves" : (kind === "co" ? (/SHARE|EQUITY|CAPITAL/.test(up) && !/CURRENT|DRAWING/.test(up) ? "share" : "reserves") : "capital");
    if (has("reserves & surplus")) return "reserves";
    if (has("fixed assets")) return /SOFTWARE|GOODWILL|TRADEMARK|PATENT|COPYRIGHT|LICEN[CS]E|INTANGIBLE/.test(up) ? "intang" : /CAPITAL WORK|CWIP|UNDER CONSTRUCTION/.test(up) ? "cwip" : "ppe";
    if (has("investments")) return /MUTUAL FUND|\bMF\b|LIQUID|\bSIP\b/.test(up) ? "ci" : "nci";
    if (has("stock-in-hand")) return "inv";
    if (has("sundry debtors")) return dr ? "tr" : "ocl";                             // a customer in credit: an advance received
    if (has("sundry creditors")) return dr ? "stla" : "tp";                          // a supplier in debit: an advance paid
    if (has("cash-in-hand")) return dr ? "cash" : "stb";
    if (has("bank od a/c") || has("bank occ a/c")) return dr ? "cash" : "stb";
    if (has("bank accounts")) return dr ? "cash" : "stb";                            // a bank in credit is an overdraft
    if (has("secured loans") || has("unsecured loans") || has("loans (liability)")) return /CREDIT CARD|OVERDRAFT|\bOD\b|\bCC\b|CASH CREDIT/.test(up + " " + n.path.join(" ").toUpperCase()) ? "stb" : (dr ? "stla" : "ltb");
    if (/DEFERRED TAX/.test(up)) return dr ? "dta" : "dtl";
    if (has("provisions")) return /GRATUITY|LEAVE/.test(up) ? "ltp" : "stp";
    if (has("duties & taxes")) return dr ? "stla" : "ocl";                           // input credit and tax paid in advance are assets
    if (has("deposits (asset)")) return /FIXED DEPOSIT|\bFD\b|FDR/.test(up + " " + n.path.join(" ").toUpperCase()) ? "cash" : (/SECURITY|RENT DEPOSIT/.test(up) ? "ltla" : "stla");
    if (has("loans & advances (asset)")) return dr ? "stla" : "ocl";
    if (has("current assets")) return dr ? (/FIXED DEPOSIT|\bFD\b/.test(up + " " + n.path.join(" ").toUpperCase()) ? "cash" : /TDS|TCS|INCOME TAX|GST|ADVANCE TAX|REFUND/.test(up + " " + n.path.join(" ").toUpperCase()) ? "stla" : "oca") : "ocl";
    if (has("current liabilities")) return dr ? "stla" : "ocl";
    if (has("misc. expenses (asset)")) return "onca";
    if (has("suspense a/c")) return dr ? "oca" : "ocl";
    return dr ? "oca" : "ocl";
  },
  // one set of statements for a year, from the ledgers' balances and the year's movements
  build(fy){
    const b = S.books, c = this.cfg(b), from = fy + "0401", to = String(num(fy) + 1) + "0331";
    const bal = Audit.balances(from, to);
    if (!bal.ok) return {error: bal.why, from, to};
    const close = bal.at(to), open = bal.at(Audit.dayBefore(from)), lines = this.LINES[c.kind === "co" ? "co" : "nc"];
    const mv = MIS.moves(from, to), stock = c.stock || {}, integrated = Object.keys(close).some(l => this.nature(l).path.some(g => /^stock-in-hand$/i.test(g)) && Math.abs(close[l]) >= 1);
    const put = {}, det = {}, add = (k, l, v) => { put[k] = r2((put[k] || 0) + v); (det[k] = det[k] || []).push([l, r2(v)]); };
    const plLine = {}, plDet = {};
    const all = Array.from(new Set(Object.keys(close).concat(Object.keys(mv)))).sort();
    let revenueLedgersClose = 0;
    all.forEach(l => {
      const v = num(close[l]), n = this.nature(l);
      const where = (c.map || {})[l] || this.place(l, v, c.kind);
      if (n.rev){
        // the year's movement goes to the statement of profit and loss
        const m = num((mv[l] || {}).t), amt = !n.dr ? m : -m, k = where === "pur" && c.mfg ? "mat" : where;
        plLine[k] = r2((plLine[k] || 0) + amt); (plDet[k] = plDet[k] || []).push([l, r2(amt)]);
        revenueLedgersClose += v;
        return;
      }
      if (Math.abs(v) < 0.005) return;
      const side = lines.find(z => z[0] === where);
      if (!side) return add("ocl", l, v);
      const liab = ["EQ", "NCL", "CL"].includes(side[2]);
      add(where, l, liab ? v : -v);
    });
    // inventories: the stock ledgers when Tally keeps them, else the figures typed
    const stOpen = integrated ? 0 : num(stock.open), stClose = integrated ? 0 : num(stock.close);
    if (!integrated && stClose) add("inv", "Closing stock (as typed)", stClose);
    plLine.chg = r2((plLine.chg || 0) + (stOpen - stClose)); if (stOpen || stClose) plDet.chg = [["Opening stock", stOpen], ["Less: closing stock", -stClose]];
    const inc = num(plLine.rev) + num(plLine.oth), exp = ["mat", "pur", "chg", "emp", "fin", "dep", "exp"].reduce((s2, k) => s2 + num(plLine[k]), 0);
    const pbe = r2(inc - exp), pbt = r2(pbe - num(plLine.exc)), pat = r2(pbt - num(plLine.tax));
    // last year's profit, still in the income and expense ledgers at the start of the year, and the stock it carried
    const bf = r2(all.filter(l => this.nature(l).rev).reduce((a, l) => a + num(open[l]), 0) + stOpen);
    if (Math.abs(bf) >= 0.005) add("reserves", "Surplus brought forward: last year's profit not yet in the profit and loss account", bf);
    // this year's profit sits in reserves (for a firm, with the partners' capital)
    add("reserves", "Surplus: profit for the year", pat);
    const sec = s2 => lines.filter(z => z[2] === s2).reduce((a, z) => a + num(put[z[0]]), 0);
    const eqL = r2(sec("EQ") + sec("NCL") + sec("CL")), assets = r2(sec("NCA") + sec("CA"));
    // last year, when the balances before the year are known
    const py = {}; all.forEach(l => { const v = num(open[l]); if (!v || this.nature(l).rev) return; const where = (c.map || {})[l] || this.place(l, v, c.kind), side = lines.find(z => z[0] === where);
      const liab = side && ["EQ", "NCL", "CL"].includes(side[2]); const k = side ? where : "ocl"; py[k] = r2((py[k] || 0) + (liab || !side ? v : -v)); });
    if (!integrated && num(stock.open)) py.inv = r2((py.inv || 0) + num(stock.open));
    const pyRev = r2(all.filter(l => this.nature(l).rev).reduce((a, l) => a + num(open[l]), 0));
    if (pyRev) py.reserves = r2((py.reserves || 0) + pyRev + (integrated ? 0 : num(stock.open)));
    // the profit and loss balance before the year belongs to reserves; revenue ledgers carry no balance at the start of a year
    const lyCovered = MIS.covered(MIS.shift(from, -1));
    const pyPl = lyCovered ? this.plOnly(MIS.shift(from, -1), MIS.shift(to, -1), c) : null;
    // the notes a reader needs: trade payables and receivables by age, MSME, and the fixed assets
    const pays = MIS.ageing(to, "p", close), recv = MIS.ageing(to, "r", close), msme = MIS.msme();
    const fa = all.filter(l => ["ppe", "intang", "cwip"].includes((c.map || {})[l] || this.place(l, num(close[l]), c.kind)) && !this.nature(l).rev).map(l => {
      const o = -num(open[l]), cl = -num(close[l]); let addn = 0, del = 0;
      (b.vouchers || []).forEach(v => { if (v.date < from || v.date > to || v.opt || v.cancel) return; v.ent.forEach(e => { if (e.l !== l) return; if (e.a < 0 && !/DEPRECIATION/i.test(v.narr || "")) addn += -e.a; else if (e.a > 0) del += e.a; }); });
      return {l, open: r2(o), add: r2(addn), del: r2(del), close: r2(cl)};
    }).filter(x => x.open || x.close || x.add || x.del);
    return {fy, from, to, kind: c.kind, lines, put, det, py, pl: plLine, plDet, inc: r2(inc), exp: r2(exp), pbe, pbt, pat, pyPl, eqL, assets, diff: r2(eqL - assets), integrated, stock: {open: stOpen, close: stClose},
      src: bal.src, tp: {msme: r2(pays.rows.filter(p => /micro|small/i.test(msme[p.party] || "")).reduce((a, p) => a + p.total, 0)), all: r2(put.tp || 0), age: pays.sum, rows: pays.rows}, tr: {age: recv.sum, rows: recv.rows}, fa,
      eps: c.kind === "co" && num(c.shares) ? r2(pat / num(c.shares)) : null, cfg: c};
  },
  plOnly(from, to, c){
    const mv = MIS.moves(from, to), pl = {};
    Object.keys(mv).forEach(l => { const n = this.nature(l); if (!n.rev) return; const m = num(mv[l].t), amt = !n.dr ? m : -m, w = (c.map || {})[l] || this.place(l, 0, c.kind), k = w === "pur" && c.mfg ? "mat" : w; pl[k] = r2((pl[k] || 0) + amt); });
    const inc = num(pl.rev) + num(pl.oth), exp = ["mat", "pur", "chg", "emp", "fin", "dep", "exp"].reduce((s2, k) => s2 + num(pl[k]), 0);
    return Object.assign(pl, {inc: r2(inc), exp: r2(exp), pbt: r2(inc - exp - num(pl.exc)), pat: r2(inc - exp - num(pl.exc) - num(pl.tax))});
  },
  // the statements as one document
  html(d){
    const co = CO(), m = v => v == null || v === "" ? "" : INR.format(r2(v)), comp = d.kind === "co", py = d.py && Object.keys(d.py).length;
    let noteNo = 0; const notes = [], noteOf = {};
    const nOf = k => { if (!noteOf[k]) { noteOf[k] = ++noteNo; notes.push(k); } return noteOf[k]; };
    const head = (a, c2) => '<tr><td colspan="4" style="padding-top:8px"><b>' + a + "</b></td></tr>" + (c2 || "");
    let bs = '<table><thead><tr><th>Particulars</th><th class="n">Note</th><th class="n">31 March ' + (num(d.fy) + 1) + '</th><th class="n">' + (py ? "31 March " + d.fy : "") + "</th></tr></thead><tbody>";
    const row = (z, pv) => { const v = num(d.put[z[0]]); if (!v && !num((d.py || {})[z[0]])) return ""; return "<tr><td>\u2003" + esc(z[1]) + '</td><td class="n">' + nOf(z[0]) + '</td><td class="n">' + m(v) + '</td><td class="n">' + (py ? m((d.py || {})[z[0]]) : "") + "</td></tr>"; };
    const secTot = s2 => d.lines.filter(z => z[2] === s2).reduce((a, z) => a + num(d.put[z[0]]), 0), secPy = s2 => d.lines.filter(z => z[2] === s2).reduce((a, z) => a + num((d.py || {})[z[0]]), 0);
    bs += head("I. EQUITY AND LIABILITIES");
    [["EQ", comp ? "Shareholders' funds" : "Owners' funds"], ["NCL", "Non-current liabilities"], ["CL", "Current liabilities"]].forEach(([s2, l], i) => { bs += head("(" + (i + 1) + ") " + l) + d.lines.filter(z => z[2] === s2).map(z => row(z)).join(""); });
    bs += '<tr><td><b>TOTAL</b></td><td></td><td class="n"><b>' + m(d.eqL) + '</b></td><td class="n"><b>' + (py ? m(secPy("EQ") + secPy("NCL") + secPy("CL")) : "") + "</b></td></tr>";
    bs += head("II. ASSETS");
    [["NCA", "Non-current assets"], ["CA", "Current assets"]].forEach(([s2, l], i) => { bs += head("(" + (i + 1) + ") " + l) + d.lines.filter(z => z[2] === s2).map(z => row(z)).join(""); });
    bs += '<tr><td><b>TOTAL</b></td><td></td><td class="n"><b>' + m(d.assets) + '</b></td><td class="n"><b>' + (py ? m(secPy("NCA") + secPy("CA")) : "") + "</b></td></tr></tbody></table>";
    const plRow = (k, l, pv) => { const v = num(d.pl[k]); if (!v && !(d.pyPl && num(d.pyPl[k]))) return ""; return "<tr><td>\u2003" + esc(l) + '</td><td class="n">' + nOf("pl:" + k) + '</td><td class="n">' + m(v) + '</td><td class="n">' + (d.pyPl ? m(d.pyPl[k]) : "") + "</td></tr>"; };
    const L = Object.fromEntries(this.PL);
    let pl = '<table><thead><tr><th>Particulars</th><th class="n">Note</th><th class="n">Year to 31 March ' + (num(d.fy) + 1) + '</th><th class="n">' + (d.pyPl ? "Year to 31 March " + d.fy : "") + "</th></tr></thead><tbody>" +
      plRow("rev", "I. " + L.rev) + plRow("oth", "II. " + L.oth) + '<tr><td><b>III. Total income (I + II)</b></td><td></td><td class="n"><b>' + m(d.inc) + '</b></td><td class="n"><b>' + (d.pyPl ? m(d.pyPl.inc) : "") + "</b></td></tr>" +
      '<tr><td colspan="4"><b>IV. Expenses</b></td></tr>' + ["mat", "pur", "chg", "emp", "fin", "dep", "exp"].map(k => plRow(k, L[k])).join("") +
      '<tr><td><b>Total expenses</b></td><td></td><td class="n"><b>' + m(d.exp) + '</b></td><td class="n"><b>' + (d.pyPl ? m(d.pyPl.exp) : "") + "</b></td></tr>" +
      '<tr><td><b>V. Profit before exceptional items and tax</b></td><td></td><td class="n"><b>' + m(d.pbe) + "</b></td><td></td></tr>" + plRow("exc", "VI. " + L.exc) +
      '<tr><td><b>VII. Profit before tax</b></td><td></td><td class="n"><b>' + m(d.pbt) + '</b></td><td class="n"><b>' + (d.pyPl ? m(d.pyPl.pbt) : "") + "</b></td></tr>" + plRow("tax", "VIII. " + L.tax) +
      '<tr><td><b>IX. Profit for the year</b></td><td></td><td class="n"><b>' + m(d.pat) + '</b></td><td class="n"><b>' + (d.pyPl ? m(d.pyPl.pat) : "") + "</b></td></tr>" +
      (d.eps != null ? "<tr><td>X. Earnings per equity share (basic and diluted)</td><td></td><td class=\"n\">" + d.eps.toFixed(2) + "</td><td></td></tr>" : "") + "</tbody></table>";
    // the notes: the ledgers behind each line, and the ones the formats ask for
    const lab = k => (d.lines.find(z => z[0] === k) || [0, (this.PL.find(z => "pl:" + z[0] === k) || [0, k])[1]])[1];
    let nt = "";
    notes.forEach(k => {
      const list = k.startsWith("pl:") ? (d.plDet[k.slice(3)] || []) : (d.det[k] || []);
      nt += '<h3 style="font-size:13px;margin:12px 0 4px">Note ' + noteOf[k] + ". " + esc(lab(k)) + "</h3>";
      if (k === "tp") nt += '<p class="note">Micro and small enterprises: ' + m(d.tp.msme) + "; others: " + m(d.tp.all - d.tp.msme) + ". Outstanding by age from the bill date: " + MIS.BUCKETS.map((z, i) => z[1] + " days " + m(d.tp.age.b[i])).join("; ") + ".</p>";
      if (k === "tr") nt += '<p class="note">Outstanding by age from the bill date: ' + MIS.BUCKETS.map((z, i) => z[1] + " days " + m(d.tr.age.b[i])).join("; ") + ". Undisputed, considered good unless shown otherwise.</p>";
      if (k === "ppe" && d.fa.length) nt += '<table><thead><tr><th>Asset</th><th class="n">Opening</th><th class="n">Additions</th><th class="n">Deductions</th><th class="n">Closing</th></tr></thead><tbody>' +
        d.fa.map(x => "<tr><td>" + esc(x.l) + '</td><td class="n">' + m(x.open) + '</td><td class="n">' + m(x.add) + '</td><td class="n">' + m(x.del) + '</td><td class="n">' + m(x.close) + "</td></tr>").join("") + "</tbody></table>";
      nt += "<table><tbody>" + list.slice().sort((a, c2) => Math.abs(c2[1]) - Math.abs(a[1])).slice(0, 60).map(([l, v]) => "<tr><td>" + esc(l) + '</td><td class="n">' + m(v) + "</td></tr>").join("") +
        (list.length > 60 ? '<tr><td class="note">and ' + (list.length - 60) + " more ledgers</td><td></td></tr>" : "") + "</tbody></table>";
    });
    const title = comp ? "Balance Sheet as at 31 March " + (num(d.fy) + 1) : "Balance Sheet as at 31 March " + (num(d.fy) + 1);
    return '<div style="text-align:center;margin-bottom:10px"><h1 style="font-size:18px;margin:0">' + esc(co.name) + '</h1><div class="note">' + (comp ? "Schedule III to the Companies Act, 2013 (Division I)" : "Format of the ICAI Guidance Note on Financial Statements of Non-Corporate Entities") + "</div></div>" +
      "<h2>" + title + "</h2>" + bs + (Math.abs(d.diff) >= 1 ? '<p class="bad">The balance sheet does not tally by \u20b9' + m(d.diff) + ": " + (d.integrated ? "check the opening balances." : "type the opening and closing stock, or check the opening balances.") + "</p>" : "") +
      (d.lines.some(z => num(d.put[z[0]]) < -0.5) ? '<p class="bad">Negative on the balance sheet, to be looked at: ' + d.lines.filter(z => num(d.put[z[0]]) < -0.5).map(z => esc(z[1]) + " " + m(d.put[z[0]])).join("; ") + ". Place those ledgers on the other side on the Mapping tab, or correct them in Tally.</p>" : "") +
      "<h2>Statement of Profit and Loss for the year ended 31 March " + (num(d.fy) + 1) + "</h2>" + pl + "<h2>Notes</h2>" + nt +
      '<p class="note">From the books in Tally (' + esc(d.src || "") + "). A draft for the auditor: accounting policies, contingent liabilities, related parties and the other disclosures are added from the records.</p>";
  }
};

/* ---------- the Accounts tab: the financial statements, and where each ledger goes ---------- */
function fsYears(){ const ms = GSTR.months(); return Array.from(new Set(ms.map(m => Audit.fyStart(m + "01").slice(0, 4)))).sort().reverse(); }
async function fsExcel(d){
  await ensureXlsx();
  const wb = XLSX.utils.book_new(), add = (n, rows) => XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet(rows), n.slice(0, 31));
  const pyOn = d.py && Object.keys(d.py).length;
  add("Balance Sheet", [["Particulars", "31 Mar " + (num(d.fy) + 1)].concat(pyOn ? ["31 Mar " + d.fy] : [])].concat(d.lines.filter(z => num(d.put[z[0]]) || num((d.py || {})[z[0]])).map(z => [FS.SECTIONS[z[2]] + ": " + z[1], num(d.put[z[0]])].concat(pyOn ? [num(d.py[z[0]])] : [])))
    .concat([["Total equity and liabilities", d.eqL], ["Total assets", d.assets], ["Difference", d.diff]]));
  add("Profit and Loss", [["Particulars", "Year to 31 Mar " + (num(d.fy) + 1)]].concat(FS.PL.filter(z => num(d.pl[z[0]])).map(z => [z[1], num(d.pl[z[0]])])).concat([["Total income", d.inc], ["Total expenses", d.exp], ["Profit before tax", d.pbt], ["Profit for the year", d.pat]]));
  add("Ledgers", [["Line", "Ledger", "Amount"]].concat(Object.entries(d.det).flatMap(([k, list]) => list.map(([l, v]) => [(d.lines.find(z => z[0] === k) || [0, k])[1], l, v])))
    .concat(Object.entries(d.plDet).flatMap(([k, list]) => list.map(([l, v]) => ["P&L: " + ((FS.PL.find(z => z[0] === k) || [0, k])[1]), l, v]))));
  if (d.fa.length) add("Fixed assets", [["Asset", "Opening", "Additions", "Deductions", "Closing"]].concat(d.fa.map(x => [x.l, x.open, x.add, x.del, x.close])));
  saveFile(CO().name.replace(/[^A-Za-z0-9]+/g, "-") + "-financial-statements-" + d.fy + ".xlsx", new Blob([XLSX.write(wb, {bookType: "xlsx", type: "array"})], {type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"}));
}
/* ================================================================== */
/* A filter on every column of every table, and long tables that     */
/* scroll inside their own box with the heading kept in view         */
/* ================================================================== */
// Tables that already have their own filters (bills, bank, sales) are left as they are.
function gfN(n){ if (typeof GridF !== "object") return n; if (GridF.full()) return Infinity; GridF.cut = true; return n; }
const GridF = {
  pop: null,
  // which screen this is, so a filter stays with its own table
  where(){ const s = [S.view, S.tab, S.homeTab]; Object.keys(S).filter(k => /(Tab|Part|Scope)$/.test(k) && typeof S[k] === "string").sort().forEach(k => s.push(k + "=" + S[k])); return s.join("|"); },
  heads(t){ const tr = t.tHead && t.tHead.rows[t.tHead.rows.length - 1]; return tr ? Array.from(tr.cells) : []; },
  label(th){ return String((th.querySelector(".gfl") || th).textContent || "").trim(); },
  key(t, i){ return this.where() + "|" + i + "|" + this.heads(t).map(th => this.label(th)).join("/"); },
  st(t){ S.gridF = S.gridF || {}; const k = t.dataset.gfkey; return S.gridF[k] = S.gridF[k] || {}; },
  // data rows: one cell per heading, none spanning; totals and section rows are left alone
  rows(t){ const n = this.heads(t).length; return Array.from(t.tBodies).flatMap(tb => Array.from(tb.rows)).filter(r => r.cells.length === n && !Array.from(r.cells).some(c => c.colSpan > 1) && !r.classList.contains("gf-sum")); },
  first(c){ const tx = String(c.innerText || c.textContent || "").trim(); return tx.split("\n")[0].trim(); },
  num(s){ let t = String(s || "").replace(/[₹,\s%]/g, ""); const neg = /^\(.*\)$/.test(t); t = t.replace(/[()]/g, ""); if (!/^-?\d+(\.\d+)?$/.test(t)) return null; return (neg ? -1 : 1) * Number(t); },
  isNum(t, i, rows){ const th = this.heads(t)[i]; if (th && th.classList.contains("n")) return true; let n = 0, k = 0; rows.forEach(r => { const v = this.first(r.cells[i]); if (v && v !== "\u2014"){ n++; if (this.num(v) != null) k++; } }); return n > 0 && k / n >= 0.9; },
  // tables cut short for speed (gfN) show every row once a filter is set on their screen, so a filter finds them all
  full(){ const w = this.where() + "|"; return Object.keys(S.gridF || {}).some(k => k.startsWith(w) && Object.values(S.gridF[k] || {}).some(f => this.active(f))); },
  cut: false, cutSeen: false,
  active(f){ return !!f && ((f.sel && f.sel.length) || f.q || f.from || f.to || f.min !== undefined && f.min !== "" || f.max !== undefined && f.max !== ""); },
  // a date as shown ("01 Apr 2025", "30 Sept 2025", "01/04/2025", "2025-04-01") to yyyy-mm-dd, or ""
  MON: {jan: 1, feb: 2, mar: 3, apr: 4, may: 5, jun: 6, jul: 7, aug: 8, sep: 9, sept: 9, oct: 10, nov: 11, dec: 12},
  date(s){
    const x = String(s || "").trim(), p2 = n => String(n).padStart(2, "0");
    let m = x.match(/^(\d{4})-(\d{2})-(\d{2})/); if (m) return m[1] + "-" + m[2] + "-" + m[3];
    m = x.match(/^(\d{1,2})[\s\-\/.]+([A-Za-z]{3,4}|\d{1,2})[\s\-\/.,]+(\d{4})\b/); if (!m) return "";
    const mo = /\d/.test(m[2]) ? +m[2] : this.MON[m[2].toLowerCase()];
    return mo >= 1 && mo <= 12 && +m[1] >= 1 && +m[1] <= 31 ? m[3] + "-" + p2(mo) + "-" + p2(m[1]) : "";
  },
  isDate(t, i, rows){ let n = 0, k = 0; rows.slice(0, 200).forEach(r => { const v = this.first(r.cells[i]); if (v && v !== "\u2014"){ n++; if (this.date(v)) k++; } }); return n > 0 && k / n >= 0.9; },
  // the quick ranges, as on the purchase page (the year runs April to March)
  quick(q){
    const d = new Date(), y = d.getFullYear(), m = d.getMonth(), iso = x => x.getFullYear() + "-" + String(x.getMonth() + 1).padStart(2, "0") + "-" + String(x.getDate()).padStart(2, "0");
    const qs = m - (m + 9) % 3, fy = m >= 3 ? y : y - 1;
    const r = {month: [new Date(y, m, 1), new Date(y, m + 1, 0)], last: [new Date(y, m - 1, 1), new Date(y, m, 0)], quarter: [new Date(y, qs, 1), new Date(y, qs + 3, 0)],
      fy: [new Date(fy, 3, 1), new Date(fy + 1, 2, 31)], lastfy: [new Date(fy - 1, 3, 1), new Date(fy, 2, 31)]}[q];
    return r ? [iso(r[0]), iso(r[1])] : null;
  },
  pass(r, f, i, num){
    const c = r.cells[i], v = this.first(c), all = String(c.innerText || "").toLowerCase();
    if (f.sel && f.sel.length && !f.sel.includes(v)) return false;
    if (f.from || f.to){ const d = this.date(v); if (!d || (f.from && d < f.from) || (f.to && d > f.to)) return false; }
    if (f.q){ const words = String(f.q).toLowerCase().split(",").map(z => z.trim()).filter(Boolean); const hit = words.some(w => all.includes(w)); if (f.not ? hit : !hit) return false; }
    if (num && (f.min !== undefined && f.min !== "" || f.max !== undefined && f.max !== "")){ const x = this.num(v); if (x == null) return false; if (f.min !== "" && f.min !== undefined && x < Number(f.min)) return false; if (f.max !== "" && f.max !== undefined && x > Number(f.max)) return false; }
    return true;
  },
  // after every render: funnels on the headings, filters applied, long tables boxed
  after(){
    this.cutSeen = this.cut; this.cut = false;
    const tables = Array.from(document.querySelectorAll("#app table.bk-table"));
    tables.forEach((t, ti) => {
      // a table with filters of its own (bills, bank) is left as it is; a funnel added here is not one of those
      if (t.querySelector(".colf:not(.gff)") || t.classList.contains("gf-off")) return;
      // React draws its headings again only when they change: the funnel is added beside them, not by rewriting them
      const own = typeof reactOwned === "function" && reactOwned(t);
      const hs = this.heads(t); if (!hs.length) return;
      const rows = this.rows(t);
      t.dataset.gfkey = this.key(t, ti);
      if (rows.length >= 4) hs.forEach((th, i) => {
        if (th.querySelector(".gff") || !this.label(th) || th.querySelector("input")) return;
        const btn = '<button class="colf gff" data-gfi="' + i + '" aria-label="Filter" title="Filter this column">' + FUNNEL + "</button>";
        if (own) th.insertAdjacentHTML(th.classList.contains("n") ? "afterbegin" : "beforeend", btn);
        else th.innerHTML = '<span class="colh"><span class="gfl">' + th.innerHTML + "</span>" + btn + "</span>";
      });
      this.apply(t);
      const wrap = t.closest(".bk-tablewrap");
      if (wrap && rows.length > 18) wrap.classList.add("gf-scroll");
    });
    if (this.pop){ const t = document.querySelector('#app table.bk-table[data-gfkey="' + CSS.escape(this.pop.key) + '"]'); if (!t) this.close(); else this.place(t); }
  },
  apply(t){
    const f = this.st(t), rows = this.rows(t), hs = this.heads(t), on = Object.keys(f).filter(i => this.active(f[i]));
    const nums = {}; on.forEach(i => { nums[i] = this.isNum(t, +i, rows); });
    // a filter set on a screen whose tables were cut short: drawn again with every row, then filtered
    if (on.length && this.cutSeen && !this.redraw){ this.redraw = setTimeout(() => { this.redraw = null; render(); }, 250); }
    let shown = 0;
    // every row read first, then shown or hidden (reading text between changes would lay the page out again per row)
    const keep = rows.map(r => on.every(i => this.pass(r, f[i], +i, nums[i])));
    rows.forEach((r, k) => { r.style.display = keep[k] ? "" : "none"; if (keep[k]) shown++; });
    hs.forEach((th, i) => { const b = th.querySelector(".gff"); if (b) b.classList.toggle("on", this.active(f[i])); });
    // what is shown, and its sums, just above the table
    const wrap = t.closest(".bk-tablewrap") || t;
    let bar = wrap.previousElementSibling && wrap.previousElementSibling.classList.contains("gf-bar") ? wrap.previousElementSibling : null;
    if (!on.length){ if (bar) bar.remove(); return; }
    if (!bar){ bar = document.createElement("div"); bar.className = "gf-bar"; wrap.parentNode.insertBefore(bar, wrap); }
    const sums = [];
    hs.forEach((th, i) => { if (!this.isNum(t, i, rows) || /rate|%|days|no\.?$|number/i.test(this.label(th))) return; let s = 0, any = false; rows.forEach(r => { if (r.style.display === "none") return; const x = this.num(this.first(r.cells[i])); if (x != null){ s += x; any = true; } }); if (any) sums.push(esc(this.label(th)) + " <b>" + INR.format(r2(s)) + "</b>"); });
    bar.innerHTML = "<span>Showing <b>" + shown + "</b> of " + rows.length + "</span>" + (sums.length ? '<span class="gf-sums">' + sums.join(" \u00b7 ") + "</span>" : "") + '<button class="linkbtn" data-gfclear="' + esc(t.dataset.gfkey) + '">Clear filters</button>';
  },
  open(btn){
    const t = btn.closest("table"), i = +btn.dataset.gfi;
    if (this.pop && this.pop.key === t.dataset.gfkey && this.pop.i === i){ this.close(); return; }
    this.pop = {key: t.dataset.gfkey, i, search: ""};
    this.draw(t); this.place(t);
  },
  values(t, i){ const m = new Map(); this.rows(t).forEach(r => { const v = this.first(r.cells[i]); m.set(v, (m.get(v) || 0) + 1); }); return Array.from(m.entries()).sort((a, c) => c[1] - a[1] || String(a[0]).localeCompare(String(c[0]))); },
  draw(t){
    const p = this.pop, i = p.i, f = this.st(t)[i] || {}, rows = this.rows(t), dt = this.isDate(t, i, rows), num = !dt && this.isNum(t, i, rows), label = this.label(this.heads(t)[i]);
    let el = document.getElementById("gfpop");
    if (!el){ el = document.createElement("div"); el.id = "gfpop"; el.className = "colpop"; document.body.appendChild(el); }
    const vals = this.values(t, i), q = p.search.toLowerCase(), many = vals.length > 400;
    const shown = (q ? vals.filter(([v]) => String(v).toLowerCase().includes(q) || (f.sel || []).includes(v)) : vals).slice(0, 400);
    el.innerHTML = '<div class="cp-head"><b>' + esc(label) + '</b><button class="linkbtn" data-gfx="close" aria-label="Close">\u00d7</button></div><div class="cp-body">' +
      (dt ? '<div class="cp-quick">' + [["month", "This month"], ["last", "Last month"], ["quarter", "This quarter"], ["fy", "This year"], ["lastfy", "Last year"]].map(([v, l]) => '<button class="cp-chip" data-gfq="' + v + '">' + l + "</button>").join("") + "</div>" +
        '<div class="cp-range"><label>From<input type="date" data-gfin="from" value="' + esc(f.from || "") + '"></label><label>To<input type="date" data-gfin="to" value="' + esc(f.to || "") + '"></label></div>' : "") +
      (num ? '<div class="cp-range"><label>From<input type="text" inputmode="decimal" data-gfin="min" value="' + esc(f.min || "") + '" placeholder="any"></label><label>To<input type="text" inputmode="decimal" data-gfin="max" value="' + esc(f.max || "") + '" placeholder="any"></label></div>' : "") +
      '<div class="cp-row"><select data-gfin="not"><option value="">Has</option><option value="1"' + (f.not ? " selected" : "") + '>Does not have</option></select><input type="text" data-gfin="q" value="' + esc(f.q || "") + '" placeholder="words, commas between"></div>' +
      (vals.length > 1 && !((num || dt) && vals.length > 60) ? '<p class="cp-sub">Or only these' + (many ? " (the first 400; search to narrow)" : "") + ':</p><input type="search" class="cp-search" data-gfin="search" value="' + esc(p.search) + '" placeholder="Search\u2026">' +
        '<div class="cp-list">' + shown.map(([v, n]) => '<label class="cp-item"><input type="checkbox" data-gfv="' + esc(v) + '"' + ((f.sel || []).includes(v) ? " checked" : "") + "><span>" + esc(v === "" ? "(blank)" : v) + "</span><small>" + n + "</small></label>").join("") + "</div>" : "") +
      '</div><div class="cp-foot"><button class="btn small" data-gfx="clear">Clear</button><button class="btn small primary" data-gfx="close">Done</button></div>';
  },
  place(t){
    const el = document.getElementById("gfpop"), b = t.querySelector('.gff[data-gfi="' + this.pop.i + '"]');
    if (!el || !b) return;
    const r = b.getBoundingClientRect(), w = 252;
    el.style.left = Math.max(12, Math.min(window.innerWidth - w - 12, r.left - 8)) + "px";
    // below the funnel; above it when there is no room below, so the buttons stay on the screen
    const h = el.offsetHeight, below = r.bottom + 6;
    el.style.top = (below + h <= window.innerHeight - 8 ? below : Math.max(8, Math.min(r.top - h - 6, window.innerHeight - h - 8))) + "px";
  },
  close(){ this.pop = null; const el = document.getElementById("gfpop"); if (el) el.remove(); },
  table(){ return this.pop ? document.querySelector('#app table.bk-table[data-gfkey="' + CSS.escape(this.pop.key) + '"]') : null; },
  set(k, v){
    const t = this.table(); if (!t) return;
    const st = this.st(t), f = st[this.pop.i] = st[this.pop.i] || {};
    if (k === "search"){ this.pop.search = v; this.draw(t); const s = document.querySelector('#gfpop [data-gfin="search"]'); if (s){ s.focus(); s.setSelectionRange(v.length, v.length); } return; }
    if (k === "not") f.not = !!v; else f[k] = v;
    this.apply(t);
  }
};
document.addEventListener("click", e => {
  const b = e.target.closest && e.target.closest(".gff");
  if (b){ e.preventDefault(); e.stopPropagation(); GridF.open(b); return; }
  const c = e.target.closest && e.target.closest("[data-gfclear]");
  if (c){ const t = document.querySelector('#app table.bk-table[data-gfkey="' + CSS.escape(c.dataset.gfclear) + '"]'); if (t){ S.gridF[t.dataset.gfkey] = {}; GridF.apply(t); } GridF.close(); return; }
  const qk = e.target.closest && e.target.closest("#gfpop [data-gfq]");
  if (qk){ const t = GridF.table(), r = GridF.quick(qk.dataset.gfq); if (t && r){ const st = GridF.st(t), f = st[GridF.pop.i] = st[GridF.pop.i] || {}; f.from = r[0]; f.to = r[1]; GridF.apply(t); GridF.draw(t); } return; }
  const x = e.target.closest && e.target.closest("#gfpop [data-gfx]");
  if (x){ const t = GridF.table(); if (x.dataset.gfx === "clear" && t){ delete GridF.st(t)[GridF.pop.i]; GridF.apply(t); GridF.draw(t); } else GridF.close(); return; }
  if (GridF.pop && !(e.target.closest && e.target.closest("#gfpop"))) GridF.close();
}, true);
document.addEventListener("input", e => {
  const el = e.target;
  if (!el.closest || !el.closest("#gfpop")) return;
  if (el.dataset.gfin) GridF.set(el.dataset.gfin, el.value);
  if (el.dataset.gfv !== undefined){ const t = GridF.table(); if (!t) return; const st = GridF.st(t), f = st[GridF.pop.i] = st[GridF.pop.i] || {}; f.sel = f.sel || [];
    if (el.checked){ if (!f.sel.includes(el.dataset.gfv)) f.sel.push(el.dataset.gfv); } else f.sel = f.sel.filter(v => v !== el.dataset.gfv); GridF.apply(t); }
}, true);
document.addEventListener("keydown", e => { if (e.key === "Escape" && GridF.pop) GridF.close(); });
window.addEventListener("resize", () => { const t = GridF.table(); if (t) GridF.place(t); });
/* ================================================================== */
/* ITC follow-up: every bill and note that 2B and Tally do not agree  */
/* on, carried from month to month until it is settled                */
/* ================================================================== */
// Nothing here is typed in or remembered by hand: the list is worked out again, each time, from the books and every
// 2B brought in. Only the decision on each item, its note and the dates suppliers were written to are kept.
const ITCT = {
  CATS: {
    waiting:   {label: "In Tally, not in 2B", law: "Credit waits until the supplier reports the bill (section 16(2)(aa)); it is taken in the month it appears in 2B, up to 30 November after the year.", warn: true,
                acts: [["follow", "Follow up the supplier"], ["wait", "Wait, no letter"], ["expense", "Give up the credit: charge the tax to cost"]]},
    diff:      {label: "In both, amounts differ", law: "Credit is taken on the lower of the bill and 2B; the rest waits until the supplier amends, or Tally is corrected.", warn: true,
                acts: [["supplier", "Ask the supplier to amend"], ["books", "Correct Tally"], ["accept", "Accept: the lower is final"]]},
    tobook:    {label: "In 2B, not in Tally", law: "Credit needs the bill in the books and the goods or services received (section 16(2)); book it, or keep it pending or reject it in IMS.", warn: true,
                acts: [["book", "Book it in Tally"], ["pending", "Keep pending in IMS, book later"], ["reject", "Not ours: reject in IMS"]]},
    nocredit:  {label: "In 2B, booked without credit", law: "The bill is in Tally with the tax charged to cost, and 2B shows the credit as available.", warn: true,
                acts: [["take", "Take the credit: put the tax to input in Tally"], ["leave", "Leave it: the tax stays in cost"]]},
    suppcn:    {label: "Supplier\u2019s credit note in 2B", law: "A credit note in 2B reduces credit in that month unless it is rejected in IMS; book it in Tally as a debit note.", warn: true,
                acts: [["accept", "Accept in IMS; book it in Tally"], ["reject", "Reject in IMS: disputed"]]},
    ournote:   {label: "Note in Tally, not in 2B", law: "Credit is already reduced in the books; the supplier still has to report the note.", warn: false,
                acts: [["follow", "Follow up the supplier"], ["ok", "Nothing to do"]]},
    rejinv:    {label: "Invoice rejected in IMS", law: "A rejected invoice gives no credit. The supplier\u2019s tax stays until they amend or cancel it in GSTR-1A or a later GSTR-1; the amended document comes back to IMS. Once 3B is filed the rejection is final for that month.", warn: true,
                acts: [["keep", "Keep rejected: no credit; reverse the input tax in Tally"], ["accept", "Change to accept in IMS before filing 3B"]]},
    rejcn:     {label: "Credit note rejected in IMS", law: "A rejected credit note does not reduce your credit; the supplier\u2019s tax goes back up in their 3B. Reverse the debit note in Tally, or accept it in IMS if it is right.", warn: true,
                acts: [["keep", "Keep rejected: credit not reduced; reverse it in Tally"], ["accept", "Accept in IMS: credit reduced"]]},
    confirm:   {label: "To confirm", law: "Probably the same bill with a different number or no GSTIN in Tally: confirm it under 2B reconciliation.", warn: true, acts: []},
    unchecked: {label: "Not checked yet", law: "The 2B for the bill\u2019s month is not here, so it cannot be said whether the supplier reported it. Bring in that month\u2019s 2B.", warn: false, acts: []},
    na:        {label: "In 2B, credit not available", law: "2B marks it not available (place of supply in another state, or after the time limit); no credit, nothing to follow up.", warn: false, acts: []},
    later:     {label: "Taken in a later month", law: "Booked in one month, in 2B of a later month: the credit was taken then.", warn: false, acts: []}
  },
  store(reg){ const b = S.books; b.itcTrack = b.itcTrack || {}; const t = b.itcTrack[reg || ""] = b.itcTrack[reg || ""] || {}; t.dec = t.dec || {}; t.sent = t.sent || {}; t.contact = t.contact || {}; return t; },
  dec(reg, key){ return ((this.store(reg).dec[key]) || {}); },
  // the last day to take credit on a bill: 30 November after the end of its year (section 16(4))
  deadline(d){ const s = String(d || ""); if (s.length < 6) return ""; const y = num(s.slice(0, 4)), m = num(s.slice(4, 6)), fy = m >= 4 ? y : y - 1; return (fy + 1) + "1130"; },
  today(){ const d = new Date(); return d.getFullYear() + String(d.getMonth() + 1).padStart(2, "0") + String(d.getDate()).padStart(2, "0"); },
  tx(o){ return r2(num(o.igst) + num(o.cgst) + num(o.sgst) + num(o.cess)); },
  items(reg){
    const b = S.books, res = GST2B.run(reg), loaded = (res.loaded || []).slice().sort(), last = loaded[loaded.length - 1] || "", first = loaded[0] || "";
    const vById = new Map((b.vouchers || []).map(v => [v.id, v])), out = [], today = this.today();
    const add = (cat, o) => { const k = o.key, dd = this.dec(reg, k), c = this.CATS[cat];
      const x = Object.assign({cat, act: dd.act || (c.acts[0] ? c.acts[0][0] : ""), note: dd.note || "", decidedAt: dd.at || ""}, o);
      const closed = {na: 1, later: 1, unchecked: 1}[cat] || (cat === "waiting" && x.act === "expense") || (cat === "diff" && x.act === "accept") || (cat === "tobook" && x.act === "reject") ||
        (cat === "nocredit" && x.act === "leave") || (cat === "ournote" && x.act === "ok");
      x.open = !closed;
      out.push(x); };
    const bk = d => ({supplier: d.party, gstin: d.gstin || "", no: d.no, date: d.date, ym: d.ym, booked: d.bookDate, voucher: d.voucher, type: d.type, taxable: d.taxable, igst: d.igst, cgst: d.cgst, sgst: d.sgst, cess: d.cess, tax: this.tax(d)});
    // in Tally, not in 2B
    res.onlyBooks.forEach(d => {
      const v = vById.get(d.id);
      if (d.ineligible || (v && Books.isImport(v)) || (d.rcm && !d.gstin)) return;
      // judged only against the 2B of the bill's own month (by booking or by bill date), or a later one when that month's is here
      const covered = loaded.includes(d.ym) || loaded.includes(String(d.date).slice(0, 6)), dl = this.deadline(d.date);
      const o = Object.assign(bk(d), {key: "B|" + (d.gstin || d.party) + "|" + d.noN + "|" + d.dir, where: "Tally", since: d.ym, deadline: dl, overdue: dl && today > dl,
        checked: covered ? "not in 2B up to " + GSTR.label(last) : "no 2B here for " + GSTR.label(d.ym) + " or later", covered});
      add(!covered ? "unchecked" : d.dir > 0 ? "waiting" : "ournote", o);
    });
    // in both
    res.pairs.forEach(x => {
      const d = x.books[0], s = x.sum, t2 = this.tx(x.p), t1 = this.tx(s);
      const base = {supplier: x.p.party || d.party, gstin: x.p.gstin, no: x.p.no, date: x.p.date, ym: d.ym, booked: d.bookDate, voucher: x.books.map(z => z.voucher).join(", "), taxable: s.taxable, igst: s.igst, cgst: s.cgst, sgst: s.sgst, cess: s.cess, tax: t1,
        tax2b: t2, ym2b: x.p.ym, issues: x.issues, deadline: this.deadline(d.date)};
      if (x.status === "probable") add("confirm", Object.assign(base, {key: "C|" + x.p.key, where: "both?"}));
      else if (x.status === "diff") add("diff", Object.assign(base, {key: "D|" + x.p.gstin + "|" + x.p.noN + "|" + x.p.dir, where: "both", gap: r2(t1 - t2), claim: Math.min(t1, t2)}));
      if (x.status !== "probable" && x.books.some(z => z.ym < x.p.ym)) add("later", Object.assign({}, base, {key: "L|" + x.p.key, where: "both", claimedIn: x.p.ym}));
    });
    // rejected in IMS
    (res.rejected || []).forEach(x => {
      const p = x.p, inT = x.books.length > 0, s2 = x.sum;
      const o = {supplier: p.party, gstin: p.gstin, no: p.no, date: p.date, ym: p.ym, ym2b: p.ym, taxable: inT ? s2.taxable : p.taxable, igst: inT ? s2.igst : p.igst, cgst: inT ? s2.cgst : p.cgst, sgst: inT ? s2.sgst : p.sgst, cess: inT ? s2.cess : p.cess,
        tax: inT ? this.tax(s2) : this.tax(p), tax2b: this.tax(p), where: inT ? "both" : "2B", key: "R|" + p.key, deadline: this.deadline(p.date), ims: "rejected", remarks: p.remarks || "",
        booked: inT ? x.books[0].bookDate : "", voucher: x.books.map(d => d.voucher).join(", "), bookedAs: inT ? "" : "not booked", issues: p.remarks ? ["your remark: " + p.remarks] : []};
      const cat = p.dir < 0 ? "rejcn" : "rejinv";
      add(cat, o);
      if (!inT){ const last = out[out.length - 1]; last.open = false; last.act = "keep"; }
    });
    // in 2B, not in Tally
    res.only2b.forEach(p => {
      const base = {supplier: p.party, gstin: p.gstin, no: p.no, date: p.date, ym: p.ym, ym2b: p.ym, taxable: p.taxable, igst: p.igst, cgst: p.cgst, sgst: p.sgst, cess: p.cess, tax: this.tax(p), tax2b: this.tax(p),
        where: "2B", key: "P|" + p.gstin + "|" + p.noN + "|" + p.dir, deadline: this.deadline(p.date), reason: p.itcavl === "N" ? (p.rsn === "P" ? "place of supply" : p.rsn === "C" ? "after the time limit" : "not available") : "",
        bookedAs: p.bookedNoCredit ? p.bookedNoCredit.type + " " + (p.bookedNoCredit.no || "") + " of " + GSTAmend.dmy(p.bookedNoCredit.date) : "", ims: p.ims ? GST2B.IMS[p.ims] || p.ims : ""};
      if (p.itcavl === "N") add("na", base);
      else if (p.dir < 0) add("suppcn", base);
      else if (p.bookedNoCredit) add("nocredit", base);
      else add("tobook", base);
    });
    return {items: out, loaded, last, first, missing: this.missingMonths(loaded)};
  },
  tax(o){ return r2(num(o.igst) + num(o.cgst) + num(o.sgst) + num(o.cess)); },
  // months of the books with no 2B here: nothing can be followed up for them
  missingMonths(loaded){ const have = new Set(loaded); return GSTR.months().filter(m => !have.has(m)); },
  // what to write to one supplier: its bills not in 2B, and the ones that differ
  letter(reg, gstin, party, items){
    const co = CO(), m = v => INR.format(r2(v || 0));
    const w = items.filter(x => x.cat === "waiting" && x.act === "follow"), d = items.filter(x => x.cat === "diff" && x.act === "supplier"), n = items.filter(x => x.cat === "ournote" && x.act === "follow"),
      rj = items.filter(x => (x.cat === "rejinv" || x.cat === "rejcn") && x.act === "keep");
    let t = "Dear " + (party || "Sir/Madam") + ",\n\nWe are " + co.name + (co.gstin || gstin ? " (GSTIN " + ((GSTR.gstins(S.books) || []).find(g => g.slice(0, 2) === reg) || co.gstin || "") + ")" : "") + ". Our GST credit depends on your returns, so please look at the following:\n";
    if (w.length) t += "\n1. Invoices in our books that do not appear in our GSTR-2B. Please report them in your GSTR-1 / IFF:\n" + w.map((x, i) => "   " + (i + 1) + ". Invoice " + x.no + " dated " + GSTAmend.dmy(x.date) + ", taxable " + m(x.taxable) + ", tax " + m(x.tax)).join("\n") + "\n";
    if (d.length) t += "\n" + (w.length ? "2" : "1") + ". Invoices reported with different figures. Please amend them in your GSTR-1:\n" + d.map((x, i) => "   " + (i + 1) + ". Invoice " + x.no + " dated " + GSTAmend.dmy(x.date) + ": tax " + m(x.tax) + " in our books, " + m(x.tax2b) + " in your return" + (x.issues && x.issues.length ? " (" + x.issues.filter(z => !/^booked in|^value differs/.test(z)).join("; ") + ")" : "")).join("\n") + "\n";
    if (n.length) t += "\n" + (1 + (w.length ? 1 : 0) + (d.length ? 1 : 0)) + ". Credit notes you issued to us that are not in your return:\n" + n.map((x, i) => "   " + (i + 1) + ". Note " + x.no + " dated " + GSTAmend.dmy(x.date) + ", tax " + m(x.tax)).join("\n") + "\n";
    if (rj.length) t += "\n" + (1 + (w.length ? 1 : 0) + (d.length ? 1 : 0) + (n.length ? 1 : 0)) + ". Documents we have rejected in the Invoice Management System. Please amend or cancel them in your GSTR-1A / GSTR-1:\n" + rj.map((x, i) => "   " + (i + 1) + ". " + (x.cat === "rejcn" ? "Credit note " : "Invoice ") + x.no + " dated " + GSTAmend.dmy(x.date) + ", tax " + m(x.tax2b) + (x.remarks ? " (" + x.remarks + ")" : "")).join("\n") + "\n";
    t += "\nThe last date for us to take this credit is 30 November after the end of the year of each invoice. Please confirm once reported.\n\nRegards,\n" + co.name;
    return {text: t, n: w.length + d.length + n.length + rj.length};
  },
  suppliers(reg, items){
    const m = {};
    items.filter(x => x.open && ((x.cat === "waiting" && x.act === "follow") || (x.cat === "diff" && x.act === "supplier") || (x.cat === "ournote" && x.act === "follow") || ((x.cat === "rejinv" || x.cat === "rejcn") && x.act === "keep"))).forEach(x => {
      const k = x.gstin || x.supplier, s = m[k] = m[k] || {key: k, gstin: x.gstin, party: x.supplier, items: [], tax: 0, oldest: x.date, deadline: x.deadline};
      s.items.push(x); s.tax = r2(s.tax + (x.cat === "diff" ? Math.abs(x.gap) : x.cat === "rejcn" || x.cat === "rejinv" ? x.tax2b : x.tax)); if (String(x.date) < String(s.oldest)) s.oldest = x.date; if (x.deadline && (!s.deadline || x.deadline < s.deadline)) s.deadline = x.deadline;
    });
    const st = this.store(reg), b = S.books, info = b.ledInfo || {};
    return Object.values(m).map(s => { const k = GSTSet.contact(s.gstin, s.party, st.contact[s.key]), sent = st.sent[s.key] || [];
      return Object.assign(s, {email: k.email, phone: k.phone, sent, lastSent: sent[sent.length - 1] || ""}); }).sort((a, c) => c.tax - a.tax);
  },
  tallyEmail(party){ const i = ((S.books.ledInfo || {})[party]) || {}; return i.email || ""; },
  tallyPhone(party){ const i = ((S.books.ledInfo || {})[party]) || {}; return i.phone || ""; }
};

// the ITC follow-up page: React (app/src/screens/gst/ItcFollow.jsx)
function itctSupplier(key){ const reg = S.gstReg || "", R = ITCT.items(reg), s = ITCT.suppliers(reg, R.items).find(z => z.key === key); return s ? {reg, s, L: ITCT.letter(reg, s.gstin, s.party, s.items)} : null; }
// what the user decides on a line, and a note to it (kept, carried to later months)
function itctSetAct(key, act){ const st = ITCT.store(S.gstReg || ""); st.dec[key] = Object.assign({}, st.dec[key], {act, at: ITCT.today()}); saveBooks(); render(); }
function itctSetNote(key, note){ const st = ITCT.store(S.gstReg || ""); st.dec[key] = Object.assign({}, st.dec[key], {note}); saveBooks(); }
// one letter to a supplier with every bill waiting on them: copied, or opened in the mail app or WhatsApp; logged as written
function itctWrite(how, key){
  const x = itctSupplier(key); if (!x) return;
  if (how === "itctCopy") (navigator.clipboard ? navigator.clipboard.writeText(x.L.text) : Promise.reject()).then(() => toast("Letter copied."), () => toast("Could not copy; use the Excel."));
  if (how === "itctMail"){ if (!x.s.email){ toast("Type the supplier's email first."); return; } window.open("mailto:" + encodeURIComponent(x.s.email) + "?subject=" + encodeURIComponent("GST: invoices not in our GSTR-2B") + "&body=" + encodeURIComponent(x.L.text), "_blank"); }
  if (how === "itctWa"){ const ph = String(x.s.phone || "").replace(/\D/g, ""); if (!ph){ toast("Type the supplier's phone first."); return; } window.open("https://wa.me/" + (ph.length === 10 ? "91" + ph : ph) + "?text=" + encodeURIComponent(x.L.text), "_blank"); }
  itctLogSent(x.reg, x.s.key); render();
}
function itctLogSent(reg, key){ const st = ITCT.store(reg); st.sent[key] = (st.sent[key] || []).concat([ITCT.today()]); saveBooks(); }
async function itctExcel(){
  await ensureXlsx();
  const reg = S.gstReg || "", R = ITCT.items(reg), wb = XLSX.utils.book_new(), d = s => GSTAmend.dmy(s);
  const actLabel = x => ((ITCT.CATS[x.cat].acts.find(a => a[0] === x.act) || [])[1]) || "";
  const row = x => [ITCT.CATS[x.cat].label, x.supplier, x.gstin, x.no, d(x.date), x.where === "2B" ? (x.bookedAs || "not booked") : d(x.booked || x.date) + " " + (x.voucher || ""), x.where === "Tally" ? (x.covered ? "not in 2B" : "no 2B yet") : GSTR.label(x.ym2b || x.ym),
    x.taxable, x.igst, x.cgst, x.sgst, x.cess, x.tax, x.tax2b != null ? x.tax2b : "", x.deadline ? d(x.deadline) : "", actLabel(x), x.note, (x.issues || []).join("; ")];
  const head = ["What", "Supplier", "GSTIN", "Bill no.", "Bill date", "In Tally", "In 2B", "Taxable", "IGST", "CGST", "SGST", "Cess", "Tax", "Tax in 2B", "Last date for credit", "What to do", "Note", "Differences"];
  XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet([head].concat(R.items.filter(x => x.open).map(row))), "Open");
  // what to do on the portal's IMS, taken from the decisions
  const ims = R.items.filter(x => (x.where === "2B" && (x.cat === "tobook" || x.cat === "suppcn" || x.cat === "nocredit")) || x.cat === "rejinv" || x.cat === "rejcn").map(x => [x.supplier, x.gstin, x.no, d(x.date), GSTR.label(x.ym2b), x.tax2b != null ? x.tax2b : x.tax,
    x.cat === "rejinv" || x.cat === "rejcn" ? (x.act === "accept" ? "Change to Accept" : "Leave rejected") : x.cat === "suppcn" ? (x.act === "reject" ? "Reject" : "Accept") : x.act === "reject" ? "Reject" : x.act === "pending" ? "Pending" : "Accept", actLabel(x), (x.ims || "") + (x.remarks ? " \u00b7 " + x.remarks : "")]);
  XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet([["Supplier", "GSTIN", "Document", "Date", "2B month", "Tax", "IMS action", "Why", "IMS status in 2B"]].concat(ims)), "IMS actions");
  const sups = ITCT.suppliers(reg, R.items);
  XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet([["Supplier", "GSTIN", "Email", "Phone", "Bills", "Tax waiting", "Last written", "Letter"]].concat(sups.map(s => [s.party, s.gstin, s.email, s.phone, s.items.length, s.tax, s.lastSent ? d(s.lastSent) : "", ITCT.letter(reg, s.gstin, s.party, s.items).text]))), "Letters");
  XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet([head].concat(R.items.filter(x => !x.open).map(row))), "Settled");
  const g = (GSTR.gstins(S.books) || []).find(z => z.slice(0, 2) === reg) || reg;
  saveFile(CO().name.replace(/[^A-Za-z0-9]+/g, "-") + "-ITC-follow-up-" + g + "-" + ITCT.today() + ".xlsx", new Blob([XLSX.write(wb, {bookType: "xlsx", type: "array"})], {type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"}));
}
/* ================================================================== */
/* Our invoices and credit notes rejected by the customer in IMS      */
/* ================================================================== */
// The customer's IMS is theirs: nothing about their action comes to us in a file, so the rejections are marked
// here by hand, document by document, from the books' own sales. What each one does:
//  - an invoice rejected: our tax stays as reported. If the invoice is right, the customer accepts it (before their 3B)
//    or we send it again by amending it; if it is wrong, it is corrected in Tally (reported as an amendment) or cancelled
//    by a credit note.
//  - a credit note rejected: the portal adds its tax back to our liability, in the 3B of the month after the customer
//    rejected it. That add-back is put into 3.1(a) here in the same month, and taken out again if the customer later
//    accepts it (usually after we amend and send it again).
const CustIMS = {
  ACTS: {
    inv: [["ask", "Invoice is right: ask the customer to accept it, or send it again by amendment"], ["amend", "Details wrong: correct it in Tally, it goes as an amendment"], ["cancel", "Not a supply: issue a credit note"], ["done", "Settled"]],
    cn: [["rejected", "Rejected: its tax is added back to 3.1(a)"], ["accepted", "Customer accepted it later"]]
  },
  store(reg){ const b = S.books; b.outRej = b.outRej || {}; return b.outRej[reg || ""] = b.outRej[reg || ""] || {}; },
  // documents the customer can act on in IMS: invoices and notes to registered customers
  docs(reg){ return GSTR.outward(null, reg).filter(r => r.gstin && (r.kind === "B2B" || r.kind === "CDNR" || r.kind === "DBNR" || (r.kind === "EXP" && r.cls === "sez"))); },
  nextYm(ym){ const y = +ym.slice(0, 4), m = +ym.slice(4, 6); return m === 12 ? (y + 1) + "01" : y + String(m + 1).padStart(2, "0"); },
  find(reg, q){ const n = GST2B.normNo(q); if (!n) return []; return this.docs(reg).filter(r => GST2B.normNo(r.no) === n || GST2B.normNo(r.no).endsWith(n)).slice(0, 12); },
  add(reg, id){
    const r = this.docs(reg).find(z => z.id === id); if (!r) return null;
    const st = this.store(reg); if (st[id]) return st[id];
    const ym = GSTR.ym(r.date), today = ITCT.today(), rejYm = today.slice(0, 7).replace("-", "") > ym ? today.slice(0, 7).replace("-", "") : ym;
    return st[id] = {kind: r.kind === "CDNR" ? "cn" : "inv", no: r.no, date: r.date, party: r.party, gstin: r.gstin, rejYm, addYm: this.nextYm(rejYm), act: r.kind === "CDNR" ? "rejected" : "ask", remark: "", doneYm: "", at: today};
  },
  items(reg){
    const st = this.store(reg), byId = new Map(this.docs(reg).map(r => [r.id, r]));
    return Object.keys(st).map(id => { const s = st[id], r = byId.get(id);
      const tax = r ? {igst: r.igst, cgst: r.cgst, sgst: r.sgst, cess: r.cess || 0, taxable: r.taxable} : {igst: 0, cgst: 0, sgst: 0, cess: 0, taxable: 0};
      const open = s.kind === "cn" ? s.act !== "accepted" : s.act !== "done";
      return Object.assign({id, gone: !r}, s, tax, {tax: r2(tax.igst + tax.cgst + tax.sgst + tax.cess), open}); })
      .sort((a, c) => String(a.date).localeCompare(String(c.date)));
  },
  // 3.1(a) for a month: rejected credit notes added back, and taken out again in the month the customer accepts them
  month(ym, reg){
    const add = {taxable: 0, igst: 0, cgst: 0, sgst: 0, cess: 0, n: 0, list: []}, back = {taxable: 0, igst: 0, cgst: 0, sgst: 0, cess: 0, n: 0, list: []};
    const put = (o, x) => { ["taxable", "igst", "cgst", "sgst", "cess"].forEach(k => { o[k] = r2(o[k] + num(x[k])); }); o.n++; o.list.push(x); };
    if (!S.books || !S.books.outRej) return {add, back};
    this.items(reg).filter(x => x.kind === "cn" && !x.gone).forEach(x => { if (x.addYm === ym) put(add, x); if (x.act === "accepted" && x.doneYm === ym) put(back, x); });
    return {add, back};
  },
  letter(reg, gstin, party, list){
    const co = CO() || {}, g = (GSTR.gstins(S.books) || []).find(z => z.slice(0, 2) === reg) || reg, m = v => "\u20b9" + INR.format(r2(v));
    let t = "Dear Sir/Madam,\n\nThe following documents issued by " + (co.name || "us") + " (GSTIN " + g + ") to " + party + " (GSTIN " + gstin + ") are shown as rejected in your Invoice Management System:\n\n";
    t += list.map((x, i) => "   " + (i + 1) + ". " + (x.kind === "cn" ? "Credit note " : "Invoice ") + x.no + " dated " + GSTAmend.dmy(x.date) + ", taxable " + m(x.taxable) + ", tax " + m(x.tax) + (x.remark ? " (your remark: " + x.remark + ")" : "")).join("\n");
    t += "\n\nWe have checked them against our books and they are correct. Please accept them in IMS before you file GSTR-3B; if your return for that month is already filed, please let us know and we will report them again so that they come back to your IMS.\n\nRegards,\n" + (co.name || "");
    return t;
  },
  customers(reg){
    const m = {};
    this.items(reg).filter(x => x.open && ((x.kind === "inv" && x.act === "ask") || (x.kind === "cn" && x.act === "rejected"))).forEach(x => { const k = x.gstin; (m[k] = m[k] || {gstin: x.gstin, party: x.party, items: []}).items.push(x); });
    return Object.values(m).map(c => { const k = GSTSet.contact(c.gstin, c.party); return Object.assign(c, {email: k.email, phone: k.phone, tax: r2(c.items.reduce((a, x) => a + x.tax, 0))}); });
  }
};
// the "Rejected by customers in IMS" card under GSTR-1: React (app/src/screens/gst/CustIms.jsx)
// a document marked as rejected by the customer, or not after all
function custImsAdd(id){ CustIMS.add(S.gstReg || "", id); S.custImsQ = ""; GSTR._carry = null; saveBooks(); render(); }
function custImsRemove(id){ delete CustIMS.store(S.gstReg || "")[id]; GSTR._carry = null; saveBooks(); render(); }
// what is kept for one: rejYm, addYm, doneYm, act, remark
function custImsSet(id, key, val){
  const s = CustIMS.store(S.gstReg || "")[id]; if (!s) return;
  s[key] = val; if (key === "act" && val === "accepted" && !s.doneYm) s.doneYm = s.addYm;
  GSTR._carry = null; saveBooks(); if (key !== "remark") render();
}
function custImsLetter(gstin){
  const reg = S.gstReg || "", c = CustIMS.customers(reg).find(z => z.gstin === gstin); if (!c) return;
  (navigator.clipboard ? navigator.clipboard.writeText(CustIMS.letter(reg, c.gstin, c.party, c.items)) : Promise.reject()).then(() => toast("Letter copied."), () => toast("Could not copy."));
}
